const rail=[];for(let i=0;i<=150;i++)rail.push(keyPoint(i/150,-1.06));for(let i=150;i>=0;i--){const v=keyPoint(i/150,1.08);rail.push([v[0],v[1]+9])}pianoShape(rail,'piano-case');
